```latex
\documentclass[12pt]{article}
\usepackage{amsmath, amssymb}
\usepackage{geometry}
\geometry{margin=1in}
\title{SAT.4D Derived Module Summary: D1–D6}
\date{June 2025}

\begin{document}
\maketitle

\section*{D1: Dirac Bundle (Hopf Linked, Q = 2)}
\begin{align*}
\Psi_{\text{bundle}} &= \begin{pmatrix} \psi_+ \\ \psi_- \end{pmatrix} \\
m_{\text{eff}} &= \frac{m_0}{Q} = \frac{m_0}{2} \\
\mathcal{L}_{\text{Dirac}} &= \bar{\Psi} \gamma^\mu D_\mu \Psi - m_{\text{eff}} \bar{\Psi} \Psi \\
j^\mu &= \bar{\Psi} \gamma^\mu \Psi
\end{align*}

\section*{D2: SU(3) Triplet Bundle (Borromean, Q = 3)}
\begin{align*}
\Psi_{\text{triplet}} &= \begin{pmatrix} \psi_1 \\ \psi_2 \\ \psi_3 \end{pmatrix} \\
m_{\text{eff}} &= \frac{m_0}{3} \\
D_\mu \Psi &= \partial_\mu \Psi + i g_{SU(3)} T^a A^a_\mu \Psi \\
F^a_{\mu\nu} &= \partial_\mu A^a_\nu - \partial_\nu A^a_\mu + g f^{abc} A^b_\mu A^c_\nu \\
\mathcal{L}_{\text{YM}} &= -\frac{1}{4g^2} \sum_{a,\mu,\nu} (F^a_{\mu\nu})^2
\end{align*}

\section*{D3: Curvature–Mass Coupling}
\begin{align*}
m_{\text{eff}}(\phi) &= \frac{m_0}{Q} + \alpha R(\phi) \\
\mathcal{L}_{\text{Dirac}}^{\text{curved}} &= \bar{\Psi} \gamma^\mu D_\mu \Psi - m_{\text{eff}}(\phi) \bar{\Psi} \Psi \\
\omega_k &= \sqrt{k^2 + m_{\text{eff}}^2(\phi)}
\end{align*}

\section*{D4: Topological Self-Interaction}
\begin{align*}
\xi^\mu &: \text{transverse filament deformation} \\
\mathcal{L}_{\text{self}} &= \lambda_4 (\xi \cdot \xi)^2 + \lambda_6 (\xi \cdot \xi)^3 \\
\frac{\partial \mathcal{L}_{\text{self}}}{\partial \xi^\mu} &= 4\lambda_4 (\xi \cdot \xi) \xi^\mu + 6\lambda_6 (\xi \cdot \xi)^2 \xi^\mu \\
V_{\text{eff}}(\phi) &= \lambda_4 \phi^2 + \lambda_6 \phi^3,\quad \phi = \xi \cdot \xi
\end{align*}

\section*{D5: Emergent Thermal Flow and Entropy}
\begin{align*}
\theta_4(x) &= \arccos \left( \frac{v^\mu u_\mu}{\|v\|\|u\|} \right) \\
S(x) &= \sqrt{S_{\mu\nu} S^{\mu\nu}} \\
\frac{d\tau}{d\phi} &= S(x) \\
\frac{dS}{d\phi} &= S(x),\quad v^\mu_{\text{drift}} = S(x) u^\mu + \nabla^\mu S(x)
\end{align*}

\section*{D6: Cosmological Dynamics from Strain Geometry}
\begin{align*}
\left( \frac{\dot{a}}{a} \right)^2 &= S(\phi)^2 + \Lambda \\
a(\phi) &= \exp\left( \sqrt{S_0^2 + \Lambda} \cdot \phi \right) \quad \text{(for constant } S)
\end{align*}

\end{document}
```

